P=Path(__file__).resolve().parent
pack_path=P/'javascript-queue-source-pack-v1.json';pack=json.loads(pack_path.read_text());runtime_path=P/'javascript-queue-confined-linux-v1.json';runtime=json.loads(runtime_path.read_text());assert runtime['observation']['allPass']
cases=[
('factory-versus-call','Calling `pLimit(2)` returns a task Promise.','Chamar `pLimit(2)` retorna um Promise de tarefa.','`pLimit(2)` returns a limiter function. Calling that function with a task returns its caller Promise; the declaration separates `LimitFunction` from `Promise<ReturnType>`.','`pLimit(2)` retorna uma função limitadora. Chamar essa função com uma tarefa retorna seu Promise de chamador; a declaração separa `LimitFunction` de `Promise<ReturnType>`.',['limit:return','limit:generator','limit:types:pLimit','limit:types:LimitFunction.call'],['arguments-forwarded']),
('not-synchronous-start','The callback starts synchronously before the limiter call returns.','O callback começa de modo síncrono antes do retorno da chamada ao limitador.','In the frozen concurrency-one observation, two limiter calls initially report `activeCount=0` and `pendingCount=2`, with neither callback started. After one owned microtask checkpoint, the first callback has started and the counters are one and one. This is the observed scheduling of the pinned source, not a timing measurement.','Na observação congelada com concorrência um, duas chamadas ao limitador inicialmente mostram `activeCount=0` e `pendingCount=2`, sem callback iniciado. Após um checkpoint próprio de microtarefa, o primeiro callback começou e os contadores são um e um. Esse é o escalonamento observado no código fixado, sem constituir medição de tempo.',['limit:enqueue','limit:generator','limit:run'],['deferred-start']),
('clear-does-not-reject','`clearQueue` rejects every pending caller Promise.','`clearQueue` rejeita todo Promise de chamador pendente.','`clearQueue` calls the queue clear operation. In the frozen pre-start and active-task observations, discarded callbacks do not run and their caller Promises remain unsettled after 12 owned microtask checkpoints. The source does not add an explicit rejection operation to clearing; these observations do not prove universal liveness.','`clearQueue` chama a operação de limpeza da fila. Nas observações congeladas anteriores ao início e com tarefa ativa, os callbacks descartados não executam e seus Promises de chamador ficam sem resolução após 12 checkpoints próprios de microtarefas. O código não acrescenta uma operação explícita de rejeição à limpeza; essas observações não provam vivacidade universal.',['limit:defined-properties','limit:generator','queue:Queue.clear'],['clear-before-start','clear-while-active']),
('clear-does-not-cancel-active','`clearQueue` cancels a callback that is already active.','`clearQueue` cancela um callback já ativo.','In the frozen active-task observation, `clearQueue` changes pending count from one to zero while active count stays one. Releasing the owned gate lets that active task fulfill normally. The declaration also explicitly limits clearing to queued work.','Na observação congelada com tarefa ativa, `clearQueue` muda o contador pendente de um para zero enquanto o contador ativo permanece um. Liberar a barreira própria permite que essa tarefa ativa se complete normalmente. A declaração também limita explicitamente a limpeza ao trabalho na fila.',['limit:defined-properties','limit:types:LimitFunction.clearQueue','queue:Queue.clear'],['clear-while-active']),
('rejection-visible-to-caller','The empty catch in `run` swallows a task error from its caller.','O catch vazio em `run` esconde um erro de tarefa de seu chamador.','`run` passes its result Promise to the caller resolver before its internal await/catch. In the frozen throwing-task observation, the caller Promise rejects with the exact owned failure object, and the next queued task still fulfills. The empty internal catch does not make that caller outcome successful.','`run` passa seu Promise de resultado ao resolvedor do chamador antes do await/catch interno. Na observação congelada com tarefa que lança erro, o Promise do chamador é rejeitado com o objeto exato da falha própria, e a tarefa seguinte na fila ainda se completa. O catch interno vazio não torna bem-sucedido o resultado desse chamador.',['limit:run','limit:next','limit:generator'],['throw-preserves-identity']),
('infinity-accepted','Only finite positive integer concurrency values are accepted.','Apenas valores inteiros positivos e finitos de concorrência são aceitos.','The written guard accepts a positive integer or `Number.POSITIVE_INFINITY`. The frozen Infinity case returns a limiter and fulfills an owned task; the six invalid cases reject zero, a negative number, a fraction, a string, null and NaN at factory construction. This does not establish resource safety for unbounded workloads.','A condição escrita aceita um inteiro positivo ou `Number.POSITIVE_INFINITY`. O caso congelado de Infinity retorna um limitador e completa uma tarefa própria; os seis casos inválidos rejeitam zero, um número negativo, uma fração, uma string, null e NaN na construção da fábrica. Isso não estabelece segurança de recursos para cargas ilimitadas.',['limit:validation'],['infinity','invalid-zero','invalid-negative','invalid-fractional','invalid-string','invalid-null','invalid-nan']),
('noncallable-task','Passing a noncallable task throws synchronously from the limiter call.','Passar uma tarefa que não pode ser chamada lança erro síncrono na chamada ao limitador.','For the frozen input 42, the limiter call returns a Promise without a synchronous throw. That Promise later rejects with `TypeError` when the selected source tries to call the task; the final active and pending counts are zero. This is distinct from an invalid concurrency argument to the outer factory.','Para a entrada congelada 42, a chamada ao limitador retorna um Promise sem erro síncrono. Esse Promise depois é rejeitado com `TypeError` quando o código selecionado tenta chamar a tarefa; os contadores finais ativo e pendente são zero. Isso difere de um argumento inválido de concorrência para a fábrica externa.',['limit:generator','limit:enqueue','limit:run'],['invalid-task']),
('iterator-nondestructive','Iterating `Queue` consumes its queued values.','Iterar `Queue` consome os valores na fila.','The selected iterator follows local node references without updating the queue head or size. In the frozen FIFO observation, spreading three queued values preserves size three; subsequent dequeues return them in order.','O iterador selecionado segue referências locais dos nós sem atualizar a cabeça nem o tamanho da fila. Na observação FIFO congelada, espalhar três valores da fila preserva o tamanho três; as remoções posteriores os retornam em ordem.',['queue:Queue.[Symbol.iterator]','queue:Queue.dequeue','queue:types:Queue.[Symbol.iterator]'],['queue-fifo-iteration']),
('undefined-ambiguity','An `undefined` dequeue result proves the queue was empty.','Um resultado `undefined` na remoção prova que a fila estava vazia.','The selected queue accepts `undefined` as a stored value and also returns it when empty. The frozen FIFO observation distinguishes the stored value from the subsequent empty result by the size transition; the return value alone does not distinguish these cases.','A fila selecionada aceita `undefined` como valor armazenado e também o retorna quando está vazia. A observação FIFO congelada distingue o valor armazenado do resultado vazio posterior pela transição do tamanho; apenas o valor retornado não distingue esses casos.',['queue:Queue.enqueue','queue:Queue.dequeue','queue:Queue.size','queue:types:Queue.dequeue'],['queue-fifo-iteration'])]
rows=[];receipt_hash=hashlib.sha256(runtime_path.read_bytes()).hexdigest();units_hash=hashlib.sha256(pack_path.read_bytes()).hexdigest();runtime_ids={r['id']for r in runtime['observation']['rows']}
for key,en_before,pt_before,en_after,pt_after,units,observations in cases:
 assert set(units)<=set(pack['units'])and set(observations)<=runtime_ids
